import java.util.ArrayList;

public class Main {
    public static void main(String[] args) {
        ArrayList<Student> list = new ArrayList<>();
        list.add(new Student("小明", 88));
        list.add(new Student("小红", 95));
        list.add(new Student("小刚", 72));

        System.out.println("平均分 " + average(list));
        System.out.println("最高分 " + top(list).name);

        for (Student s : list) {
            System.out.println(s.name + " -> " + (s.isPass() ? "及格" : "不及格"));
        }
    }

    static double average(ArrayList<Student> list) {
        int sum = 0;
        for (Student s : list) sum += s.score;
        return sum / (double) list.size();
    }

    static Student top(ArrayList<Student> list) {
        Student best = list.get(0);
        for (Student s : list) {
            if (s.score > best.score) best = s;
        }
        return best;
    }
}

class Student {
    String name;
    int score;

    Student(String name, int score) {
        this.name = name;
        this.score = score;
    }

    boolean isPass() {
        return this.score >= 60;
    }
}

